using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CheckBrillianceAction", menuName = "Data/Battle/Battle Actions/Austra/CheckBrillianceAction Action")]
public class CheckBrillianceAction : BattleAction
{
	[Header("Effect")]
	[SerializeField]
	protected DefaultEffectAction applyEffectAction;

	[SerializeField]
	protected DefaultEffectAction criticalConfuseMultiplierEffectAction;

	public DefaultEffectAction ApplyEffectAction => applyEffectAction;

	public DefaultEffectAction CriticalConfuseMultiplierEffectAction => criticalConfuseMultiplierEffectAction;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerBrillianceGetAmount(activateFeedback: false) < 50)
		{
			applyEffectAction.CastTargetAmount(target, amount, source);
		}
		else
		{
			criticalConfuseMultiplierEffectAction.CastTargetAmount(target, 1, source);
		}
	}
}
